        "title": "📜 Catacombs Guide",
        "desc": "### 🎯 Goal\n\nGo down all **5 floors**, gather gold and defeat **Nyx, the Reaper of Nyxiel**. Gold only becomes coins if you **make it out alive**.\n\n### 🗺️ Exploration\n\n• **Arrows:** walk from room to room. Unknown rooms show up as `?`.\n\n• **Light:** every room burns candle. Below `25` it gets dark: monsters hit 25% harder and you see less.\n\n• **Guardian:** waits in the farthest room. Beating it grants a blessing and the campfire.\n\n### ⚔️ Combat\n\n• **Intent:** you always see the enemy's next move. Plan ahead!\n\n• **Guard:** blocks damage and gives +1 ✨ spark.\n\n• **Moon Bolt:** double damage that ignores shields.\n\n• **Astaroth:** a swipe that distracts the enemy and halves its next hit.\n\n### 🔥 Campfire\n\n• **Escape:** keep your gold. Miss Grey charges a Lantern Fee to guide you out if you leave early (`30%`, `20%`, `10%`).\n\n• **Descend:** more gold and more danger. Dying saves only `10%`.\n\n### 🌙 Progress\n\nEvery descent earns **Echoes** for permanent talents, even when you lose.\n\n-# 🎟️ Ticket `{ticket}` • `{entries}` descents per day • cap of `{runCap}` per descent and `{dayCap}` per day"
